import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`vc-search`,heroTitle:`Find your perfect investors in minutes`,heroSubtitle:`Perplexity Computer searches VCs that match your niche and builds a prioritized outreach list — automatically.`,heroCta:`Find my investors`,inputUrlCta:`Find my investors`,inputUrlPrefill:`Research every VC firm and investor that matches the startup category at {url}. Search Crunchbase, AngelList, and fund websites for active firms investing in this space. Map portfolio focus, check size, stage preference, and partner contacts for each firm. Build a prioritized outreach list with contact details and personalized talking points. Generate a summary of the top investor matches with next steps for each outreach.`,heroOverlaySteps:[`Analyzing your startup category and investment landscape`,`Searching Crunchbase, AngelList, and fund websites for active firms in your space`,`Mapping portfolio focus, check sizes, and partner contacts for each firm`,`Prioritized outreach list with contact details and talking points — ready to send`],generatingSteps:[`Researching the VC landscape for your startup category and stage`,`Designing an agent to search Crunchbase, AngelList, and fund websites for matching firms`,`Configuring filters for portfolio focus, check size, stage preference, and recent activity`,`Setting up outreach prioritization and partner contact extraction`],featureSectionTitle:`From category to investor shortlist`,featureCardTitles:[`Connects to your fundraising stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`LinkedIn, Google Sheets, Notion — Computer plugs into your tools so investor research and outreach happen in one workflow.`,`Ranked investor lists. Partner contact details. Portfolio overlap analysis. Personalized outreach drafts. Computer delivers everything you need to start conversations.`],capabilitySectionTitle:`Your fundraising research, on autopilot`,capabilitySectionSubtitle:`Describe your category, step away, come back to a complete investor shortlist.`,capabilityCards:[{title:`Investor Discovery`,description:`Computer can search Crunchbase, AngelList, and hundreds of fund websites to find every active VC investing in your category and stage.`},{title:`Portfolio Analysis`,description:`Computer can analyze each firm’s recent deals, portfolio companies, and thesis alignment — so you know exactly how well you fit.`},{title:`Outreach Drafts`,description:`Computer can write personalized emails referencing portfolio overlap, mutual connections, and fund thesis — ready for your review.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Notion, Gmail, and more — build workflows across your entire fundraising stack.`},{title:`Remember & Learn`,description:`Computer can remember your pitch, traction metrics, and past investor conversations across sessions — so every search builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch for new fund announcements, partner moves, and portfolio updates — and ping you when a new investor match appears.`}]});export{t as default};
